  if (limit === undefined) return DEFAULT_QUERY_LIMIT;
  if (!Number.isInteger(limit) || limit <= 0 || limit > MAX_QUERY_LIMIT) {
    throw new BacklogValidationError(
      'limit',
      `must be a positive integer ≤ ${MAX_QUERY_LIMIT}, got ${limit}`
    );
  }
  return limit;
}

