    if (!resolved) continue; // unresolved name/uid contributes nothing — never an error on a read path (§6.1)
    const edges = await graph.getEdges({ dst: resolved.id, rel: input.rel });
    for (const e of edges) union.add(e.src);
  }
  return union;
}

